import java.util.function.BinaryOperator;
import java.util.function.Function;

/** A binary tree of ints. Provided -- do not edit. */
interface TreeNode { }

/** A number sitting at the bottom of the tree. Provided -- do not edit. */
record NumberLeaf(int value) implements TreeNode { }

/** Two sub-trees added together. Provided -- do not edit. */
record SumBranch(TreeNode left, TreeNode right) implements TreeNode { }

/**
 * TASK: Write ONE recursive fold over the tree and express everything else
 * in terms of it -- no extra recursion anywhere else in this file.
 *
 * fold(node, onLeaf, onBranch):
 *   - a NumberLeaf becomes onLeaf.apply(value)
 *   - a SumBranch becomes onBranch.apply(fold(left, ...), fold(right, ...))
 *
 * With the tree  SumBranch(SumBranch(Leaf 1, Leaf 2), Leaf 3):
 *   total(tree)  -> 6            (leaves become themselves, branches add)
 *   leafCount(t) -> 3            (leaves become 1, branches add)
 *   depth(tree)  -> 3            (leaves become 1, branches take 1 + the larger side)
 *   render(tree) -> "((1+2)+3)"  (leaves become their digits, branches wrap in parentheses)
 *
 * Use `instanceof` pattern matching, e.g.
 *     if (node instanceof NumberLeaf leaf) { ... leaf.value() ... }
 */
public class ExpressionTreeFolder {

    public static <R> R fold(TreeNode node, Function<Integer, R> onLeaf, BinaryOperator<R> onBranch) {
        if (node instanceof NumberLeaf leaf) {
            return onLeaf.apply(leaf.value());
        }
        SumBranch branch = (SumBranch) node;
        return onBranch.apply(
                fold(branch.left(), onLeaf, onBranch),
                fold(branch.right(), onLeaf, onBranch));
    }

    public static int total(TreeNode node) {
        return fold(node, value -> value, (a, b) -> a + b);
    }

    public static int leafCount(TreeNode node) {
        return fold(node, value -> 1, (a, b) -> a + b);
    }

    public static int depth(TreeNode node) {
        return fold(node, value -> 1, (a, b) -> 1 + Math.max(a, b));
    }

    public static String render(TreeNode node) {
        return fold(node, String::valueOf, (a, b) -> "(" + a + "+" + b + ")");
    }
}
